INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000005-0001-0001-000000000000', 'd0000001-0001-4000-8000-000000000001', 'Print Welcome Banner', 'EASY', 'Print `Welcome to OutOfMemory Academy!` to stdout.', '["Time Limit: 2.0s"]', '[{"input": "", "output": "Welcome to OutOfMemory Academy!", "explanation": "Print welcome message"}]', 'public class Main {\n    public static void main(String[] args) {\n        System.out.println("Welcome to OutOfMemory Academy!");\n    }\n}', '[{"input": "\\n", "expected_output": "Welcome to OutOfMemory Academy!\\n", "hidden": false}]', '["basics"]', 1),
('e0000005-0001-0002-000000000000', 'd0000001-0001-4000-8000-000000000001', 'Java Edition Output', 'EASY', 'Read an integer representing Java Version (e.g. 21) and print `Java 21 Ready`.', '["Time Limit: 2.0s"]', '[{"input": "21", "output": "Java 21 Ready", "explanation": "Format output"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int v = sc.nextInt();\n        System.out.println("Java " + v + " Ready");\n    }\n}', '[{"input": "21\\n", "expected_output": "Java 21 Ready\\n", "hidden": false}, {"input": "17\\n", "expected_output": "Java 17 Ready\\n", "hidden": true}]', '["basics"]', 2),
('e0000005-0001-0003-000000000000', 'd0000001-0001-4000-8000-000000000001', 'Byte to Bit Converter', 'EASY', 'Given size in Megabytes (MB), output size in Bytes (1 MB = 1048576 Bytes).', '["Time Limit: 2.0s"]', '[{"input": "2", "output": "2097152", "explanation": "2 * 1048576"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        long mb = sc.nextLong();\n        System.out.println(mb * 1048576L);\n    }\n}', '[{"input": "2\\n", "expected_output": "2097152\\n", "hidden": false}]', '["basics"]', 3),
('e0000005-0001-0004-000000000000', 'd0000001-0001-4000-8000-000000000001', 'JDK/JRE Identifier', 'EASY', 'Given input code 1 for JDK, 2 for JRE, 3 for JVM, print its acronym name.', '["Time Limit: 2.0s"]', '[{"input": "1", "output": "Java Development Kit", "explanation": "Code 1"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int c = sc.nextInt();\n        if (c==1) System.out.println("Java Development Kit");\n        else if (c==2) System.out.println("Java Runtime Environment");\n        else System.out.println("Java Virtual Machine");\n    }\n}', '[{"input": "1\\n", "expected_output": "Java Development Kit\\n", "hidden": false}]', '["basics"]', 4),
('e0000005-0001-0005-000000000000', 'd0000001-0001-4000-8000-000000000001', 'Compiler Error Simulator', 'EASY', 'Read two numbers A and B. Print `Sum: X` on line 1 and `Product: Y` on line 2.', '["Time Limit: 2.0s"]', '[{"input": "3 4", "output": "Sum: 7\\nProduct: 12", "explanation": "Compute both"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt(), b = sc.nextInt();\n        System.out.println("Sum: " + (a + b));\n        System.out.println("Product: " + (a * b));\n    }\n}', '[{"input": "3 4\\n", "expected_output": "Sum: 7\\nProduct: 12\\n", "hidden": false}]', '["basics"]', 5);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000005-0002-0001-000000000000', 'd0000001-0002-4000-8000-000000000001', 'Memory Address Swap', 'EASY', 'Read two integers A and B, print swapped values space-separated.', '["Time Limit: 2.0s"]', '[{"input": "5 10", "output": "10 5", "explanation": "Swap values"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt(), b = sc.nextInt();\n        System.out.println(b + " " + a);\n    }\n}', '[{"input": "5 10\\n", "expected_output": "10 5\\n", "hidden": false}]', '["variables"]', 1),
('e0000005-0002-0002-000000000000', 'd0000001-0002-4000-8000-000000000001', 'Variable Re-assignment Track', 'EASY', 'Read integer A, double it 3 times, print final value.', '["Time Limit: 2.0s"]', '[{"input": "2", "output": "16", "explanation": "2 -> 4 -> 8 -> 16"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt();\n        System.out.println(a * 8);\n    }\n}', '[{"input": "2\\n", "expected_output": "16\\n", "hidden": false}]', '["variables"]', 2),
('e0000005-0002-0003-000000000000', 'd0000001-0002-4000-8000-000000000001', 'Constant PI Calculation', 'EASY', 'Given radius R, calculate perimeter `2 * 3.14159 * R`.', '["Time Limit: 2.0s"]', '[{"input": "5.0", "output": "31.4159", "explanation": "2 * PI * R"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        double r = sc.nextDouble();\n        System.out.println(2 * 3.14159 * r);\n    }\n}', '[{"input": "5.0\\n", "expected_output": "31.4159\\n", "hidden": false}]', '["variables"]', 3),
('e0000005-0002-0004-000000000000', 'd0000001-0002-4000-8000-000000000001', 'Integer Overflow Prevention', 'EASY', 'Read two 32-bit integers A and B, output their sum as a 64-bit long to prevent overflow.', '["Time Limit: 2.0s"]', '[{"input": "2000000000 2000000000", "output": "4000000000", "explanation": "Long sum"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        long a = sc.nextLong(), b = sc.nextLong();\n        System.out.println(a + b);\n    }\n}', '[{"input": "2000000000 2000000000\\n", "expected_output": "4000000000\\n", "hidden": false}]', '["variables"]', 4),
('e0000005-0002-0005-000000000000', 'd0000001-0002-4000-8000-000000000001', 'Variable Scope Shadowing', 'EASY', 'Read integer X. Print X squared plus X.', '["Time Limit: 2.0s"]', '[{"input": "4", "output": "20", "explanation": "4*4 + 4"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int x = sc.nextInt();\n        System.out.println(x * x + x);\n    }\n}', '[{"input": "4\\n", "expected_output": "20\\n", "hidden": false}]', '["variables"]', 5);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000005-0003-0001-000000000000', 'd0000001-0003-4000-8000-000000000001', 'Fahrenheit to Celsius Converter', 'EASY', 'Convert Fahrenheit F to Celsius: `(F - 32) * 5/9`.', '["Time Limit: 2.0s"]', '[{"input": "32.0", "output": "0.0", "explanation": "32 F = 0 C"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        double f = sc.nextDouble();\n        System.out.println((f - 32.0) * 5.0 / 9.0);\n    }\n}', '[{"input": "32.0\\n", "expected_output": "0.0\\n", "hidden": false}]', '["data-types"]', 2),
('e0000005-0004-0001-000000000000', 'd0000001-0004-4000-8000-000000000001', 'Formatted Scanner Bill', 'EASY', 'Read item name (string), quantity (int), price (double). Print `Item: <name>, Total: <qty*price>`.', '["Time Limit: 2.0s"]', '[{"input": "Apple 3 1.5", "output": "Item: Apple, Total: 4.5", "explanation": "Bill calculation"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String item = sc.next();\n        int q = sc.nextInt();\n        double p = sc.nextDouble();\n        System.out.println("Item: " + item + ", Total: " + (q * p));\n    }\n}', '[{"input": "Apple 3 1.5\\n", "expected_output": "Item: Apple, Total: 4.5\\n", "hidden": false}]', '["io"]', 1),
('e0000005-0005-0001-000000000000', 'd0000001-0005-4000-8000-000000000001', 'Modulus & Remainder Operator', 'EASY', 'Read dividend A and divisor B, print quotient and remainder on space separated.', '["Time Limit: 2.0s"]', '[{"input": "17 5", "output": "3 2", "explanation": "17/5=3, 17%5=2"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt(), b = sc.nextInt();\n        System.out.println((a / b) + " " + (a % b));\n    }\n}', '[{"input": "17 5\\n", "expected_output": "3 2\\n", "hidden": false}]', '["operators"]', 2);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000005-0006-0001-000000000000', 'd0000001-0006-4000-8000-000000000001', 'Maximum of Three Numbers', 'EASY', 'Given three integers A, B, C, output the maximum value.', '["Time Limit: 2.0s"]', '[{"input": "10 45 20", "output": "45", "explanation": "45 is max"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt(), b = sc.nextInt(), c = sc.nextInt();\n        System.out.println(Math.max(a, Math.max(b, c)));\n    }\n}', '[{"input": "10 45 20\\n", "expected_output": "45\\n", "hidden": false}]', '["conditionals"]', 3),
('e0000005-0007-0001-000000000000', 'd0000001-0007-4000-8000-000000000001', 'Day of Week Switch Case', 'EASY', 'Read integer 1-7 (1=Monday...7=Sunday), print Day name or INVALID.', '["Time Limit: 2.0s"]', '[{"input": "3", "output": "Wednesday", "explanation": "3 = Wednesday"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int d = sc.nextInt();\n        String[] days = {"", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"};\n        System.out.println(d >= 1 && d <= 7 ? days[d] : "INVALID");\n    }\n}', '[{"input": "3\\n", "expected_output": "Wednesday\\n", "hidden": false}]', '["conditionals"]', 1),
('e0000005-0008-0001-000000000000', 'd0000001-0008-4000-8000-000000000001', 'Bitwise AND and OR', 'EASY', 'Read two integers, print (A AND B) and (A OR B) on separate lines.', '["Time Limit: 2.0s"]', '[{"input": "5 3", "output": "1\\n7", "explanation": "5&3=1, 5|3=7"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt(), b = sc.nextInt();\n        System.out.println(a & b);\n        System.out.println(a | b);\n    }\n}', '[{"input": "5 3\\n", "expected_output": "1\\n7\\n", "hidden": false}]', '["bitwise"]', 1),
('e0000005-0009-0001-000000000000', 'd0000001-0009-4000-8000-000000000001', 'Check Power of Two', 'MEDIUM', 'Check if N is a power of 2 using bitwise operation `(N & (N - 1)) == 0`. Print YES or NO.', '["Time Limit: 2.0s"]', '[{"input": "16", "output": "YES", "explanation": "16 is 2^4"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        long n = sc.nextLong();\n        System.out.println(n > 0 && (n & (n - 1)) == 0 ? "YES" : "NO");\n    }\n}', '[{"input": "16\\n", "expected_output": "YES\\n", "hidden": false}]', '["bitwise"]', 1),
('e0000005-0010-0001-000000000000', 'd0000001-0010-4000-8000-000000000001', 'Count Set Bits (Hamming Weight)', 'MEDIUM', 'Count total number of set bits (1s) in binary representation of integer N.', '["Time Limit: 2.0s"]', '[{"input": "7", "output": "3", "explanation": "7 in binary is 111 (3 ones)"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        System.out.println(Integer.bitCount(n));\n    }\n}', '[{"input": "7\\n", "expected_output": "3\\n", "hidden": false}]', '["bitwise"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000005-0011-0001-000000000000', 'd0000001-0011-4000-8000-000000000001', 'Multiplication Table of N', 'EASY', 'Print first 10 multiples of N space-separated.', '["Time Limit: 2.0s"]', '[{"input": "3", "output": "3 6 9 12 15 18 21 24 27 30 ", "explanation": "Table of 3"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        for(int i=1; i<=10; i++) System.out.print((n * i) + " ");\n        System.out.println();\n    }\n}', '[{"input": "3\\n", "expected_output": "3 6 9 12 15 18 21 24 27 30 \\n", "hidden": false}]', '["loops"]', 2),
('e0000005-0012-0001-000000000000', 'd0000001-0012-4000-8000-000000000001', 'Reverse Digits of Number', 'EASY', 'Reverse the digits of integer N.', '["Time Limit: 2.0s"]', '[{"input": "12345", "output": "54321", "explanation": "Reversed digits"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), rev = 0;\n        while (n != 0) { rev = rev * 10 + n % 10; n /= 10; }\n        System.out.println(rev);\n    }\n}', '[{"input": "12345\\n", "expected_output": "54321\\n", "hidden": false}]', '["loops"]', 3),
('e0000005-0013-0001-000000000000', 'd0000001-0013-4000-8000-000000000001', 'Prime Number Checker', 'EASY', 'Determine if integer N > 1 is Prime. Output PRIME or NOT PRIME.', '["Time Limit: 2.0s"]', '[{"input": "29", "output": "PRIME", "explanation": "29 is prime"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        boolean p = n > 1;\n        for(int i=2; i*i<=n; i++) if(n % i == 0) { p = false; break; }\n        System.out.println(p ? "PRIME" : "NOT PRIME");\n    }\n}', '[{"input": "29\\n", "expected_output": "PRIME\\n", "hidden": false}]', '["loops"]', 1),
('e0000005-0014-0001-000000000000', 'd0000001-0014-4000-8000-000000000001', 'Right Triangle Star Pattern', 'EASY', 'Print right angle star pattern of height N.', '["Time Limit: 2.0s"]', '[{"input": "3", "output": "*\\n**\\n***", "explanation": "3 lines"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        for(int i=1; i<=n; i++) {\n            for(int j=1; j<=i; j++) System.out.print("*");\n            System.out.println();\n        }\n    }\n}', '[{"input": "3\\n", "expected_output": "*\\n**\\n***\\n", "hidden": false}]', '["patterns"]', 1),
('e0000005-0015-0001-000000000000', 'd0000001-0015-4000-8000-000000000001', 'Armstrong Number Checker', 'MEDIUM', 'Check if N is an Armstrong number (sum of cubes of digits equals N). Output YES or NO.', '["Time Limit: 2.0s"]', '[{"input": "153", "output": "YES", "explanation": "1^3 + 5^3 + 3^3 = 153"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), t = n, sum = 0;\n        while (t > 0) { int d = t % 10; sum += d*d*d; t /= 10; }\n        System.out.println(sum == n ? "YES" : "NO");\n    }\n}', '[{"input": "153\\n", "expected_output": "YES\\n", "hidden": false}]', '["loops"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000005-0016-0001-000000000000', 'd0000001-0016-4000-8000-000000000001', 'GCD Function Implementation', 'EASY', 'Find Greatest Common Divisor of A and B.', '["Time Limit: 2.0s"]', '[{"input": "12 18", "output": "6", "explanation": "GCD(12,18)=6"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt(), b = sc.nextInt();\n        while (b != 0) { int t = b; b = a % b; a = t; }\n        System.out.println(a);\n    }\n}', '[{"input": "12 18\\n", "expected_output": "6\\n", "hidden": false}]', '["functions"]', 1),
('e0000005-0017-0001-000000000000', 'd0000001-0017-4000-8000-000000000001', 'Pass by Value Simulation', 'EASY', 'Given integer A and delta D, print original A, modified A+D, and original A space-separated.', '["Time Limit: 2.0s"]', '[{"input": "10 5", "output": "10 15 10", "explanation": "Original unmodified"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt(), d = sc.nextInt();\n        System.out.println(a + " " + (a + d) + " " + a);\n    }\n}', '[{"input": "10 5\\n", "expected_output": "10 15 10\\n", "hidden": false}]', '["functions"]', 1),
('e0000005-0018-0002-000000000000', 'd0000001-0018-4000-8000-000000000001', 'Find Min and Max in Array', 'EASY', 'Given N integers, print min and max values space-separated.', '["Time Limit: 2.0s"]', '[{"input": "5\\n3 1 9 4 5", "output": "1 9", "explanation": "Min=1, Max=9"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;\n        for(int i=0; i<n; i++) {\n            int v = sc.nextInt();\n            if(v < min) min = v;\n            if(v > max) max = v;\n        }\n        System.out.println(min + " " + max);\n    }\n}', '[{"input": "5\\n3 1 9 4 5\\n", "expected_output": "1 9\\n", "hidden": false}]', '["arrays"]', 2),
('e0000005-0019-0001-000000000000', 'd0000001-0019-4000-8000-000000000001', 'Reverse an Array In-Place', 'EASY', 'Print array reversed space-separated.', '["Time Limit: 2.0s"]', '[{"input": "4\\n1 2 3 4", "output": "4 3 2 1 ", "explanation": "Reversed array"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        for(int i=n-1; i>=0; i--) System.out.print(a[i] + " ");\n        System.out.println();\n    }\n}', '[{"input": "4\\n1 2 3 4\\n", "expected_output": "4 3 2 1 \\n", "hidden": false}]', '["arrays"]', 1),
('e0000005-0020-0001-000000000000', 'd0000001-0020-4000-8000-000000000001', 'Check Array is Sorted', 'EASY', 'Determine if array of size N is sorted ascending. Print YES or NO.', '["Time Limit: 2.0s"]', '[{"input": "4\\n1 2 3 4", "output": "YES", "explanation": "Sorted"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        boolean sorted = true;\n        for(int i=0; i<n-1; i++) if(a[i] > a[i+1]) { sorted = false; break; }\n        System.out.println(sorted ? "YES" : "NO");\n    }\n}', '[{"input": "4\\n1 2 3 4\\n", "expected_output": "YES\\n", "hidden": false}]', '["arrays"]', 1);
